from datetime import datetime


def build_standard_utc_timestamp_str(date_time_instance: datetime) -> str:

    if not date_time_instance:
        raise ValueError("No date_time_instance provided")

    return f"{date_time_instance.isoformat()}Z"


def convert_standard_utc_timestamp_str_to_datetime(
    standard_utc_timestamp_str: str,
) -> datetime:

    if not standard_utc_timestamp_str:
        raise ValueError("No standard_utc_timestamp_str provided")

    # Remove the 'Z' before parsing
    iso_str = standard_utc_timestamp_str.rstrip("Z")
    # Convert ISO 8601 string to datetime object
    return datetime.fromisoformat(iso_str)
